//! 🪪️ Complete original Model and Config authority is hashed before checkpoint publication or restore.
use super::{energy_grant_covers, Model, SimulationConfig};
use semio_framework_os_store_canonical_json::{ArtifactCanonicalTreeSource,ArtifactCanonicalJson};
use semio_framework_os_store_canonical_json::ArtifactCanonicalSourceIdentityCursor as Cursor;
use semio_framework_os_store_canonical_json::ArtifactCanonicalSourceIdentityBirth as Birth;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetirementDemand,ValueError,ValueRefusalKind};
const META:usize=2*size_of::<usize>()+1;
/// 🌲️ Paid canonical cursor custody belongs to the job's immutable original roots.
#[derive(Default)]
pub struct EnergyInputIdentity{birth:Birth,cursor:Option<Box<Cursor>>,digest:Option<[u8;32]>,bytes:usize,phase:u8}
impl EnergyInputIdentity{
 /// 🌱️ A pristine receiver has never admitted a canonical cursor backing.
 pub(crate) fn is_pristine(&self)->bool{self.phase==0&&self.bytes==0&&self.cursor.is_none()&&self.digest.is_none()&&self.birth.original_backing_identity().is_none()&&self.birth.initialized_slots()==0}
 pub fn processed_bytes(&self)->usize{self.bytes}
 pub fn digest(&self)->Option<&[u8;32]>{(self.phase==5).then(||self.digest.as_ref()).flatten()}
 pub fn terminal_is_empty(&self)->bool{self.phase==8&&self.birth.terminal_is_empty()&&self.cursor.is_none()&&self.digest.is_none()}
 pub fn next_demand(&self)->RetirementDemand{match self.phase{0=>{let mut d=self.birth.next_demand();d.copy_bytes+=META;d.depth+=1;d},1=>{let mut d=self.cursor.as_ref().unwrap().next_demand();d.copy_bytes+=META;d.depth+=1;d},2=>RetirementDemand{copy_bytes:32+META,depth:1,..Default::default()},3=>{let mut d=self.cursor.as_ref().unwrap().next_demand();d.copy_bytes+=META;d.depth+=1;d},4=>RetirementDemand{copy_bytes:META,release_bytes:size_of::<Cursor>(),depth:1,..Default::default()},6 if self.cursor.as_ref().is_some_and(|cursor|!cursor.terminal_is_empty())=>RetirementDemand{copy_bytes:size_of::<Cursor>()+META,depth:2,..Default::default()},6 if self.cursor.is_some()=>RetirementDemand{copy_bytes:META,release_bytes:size_of::<Cursor>(),depth:1,..Default::default()},6=>RetirementDemand{copy_bytes:size_of::<Self>(),depth:1,..Default::default()},_=>Default::default()}}
 pub fn advance(&mut self,model:&Model,config:&SimulationConfig,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{if self.phase==5{return Ok(Default::default());}let d=self.next_demand();if !energy_grant_covers(grant,d){return Ok(Default::default());}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes,..Default::default()};match self.phase{
 0=>{let (cursor,progress)=self.birth.advance(2,RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-META,maximum_depth:grant.maximum_depth-1,..grant})?;p=progress;p.copied_bytes+=META;if let Some(cursor)=cursor{self.cursor=Some(cursor);self.phase=1;}},
 1=>{let cursor=self.cursor.as_mut().unwrap();let source:Option<&dyn ArtifactCanonicalJson>=match cursor.source_index(){Some(0)=>Some(ArtifactCanonicalTreeSource::view(model)),Some(1)=>Some(ArtifactCanonicalTreeSource::view(config)),None=>None,_=>return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy identity has only two original roots"))};let step=cursor.advance(source,RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-META,maximum_depth:grant.maximum_depth-1,..grant})?;self.bytes+=usize::from(step.byte.is_some());p=step.progress;p.copied_bytes+=META;p.copied_items=p.copied_items.max(1);if step.ready{self.phase=2;}},
 2=>{let cursor=self.cursor.as_mut().unwrap();self.digest=Some(*cursor.digest().unwrap());cursor.begin_close();self.phase=3;},
 3=>{let cursor=self.cursor.as_mut().unwrap();let step=cursor.close_step(RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-META,maximum_depth:grant.maximum_depth-1,..grant})?;p=step.progress;p.copied_bytes+=META;p.copied_items=p.copied_items.max(1);if cursor.terminal_is_empty(){self.phase=4;}},
 4=>{self.cursor=None;self.phase=5;},
 _=>return Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"Energy input authority is closing")),
 }Ok(p)}
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{if self.terminal_is_empty(){return Ok(Default::default());}self.phase=6;let d=self.close_demand();if !energy_grant_covers(grant,d){return Ok(Default::default());}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,released_bytes:d.release_bytes,..Default::default()};if !self.birth.terminal_is_empty(){p=self.birth.close_step(RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-META,maximum_depth:grant.maximum_depth-1,..grant})?;p.copied_bytes+=META;p.copied_items=p.copied_items.max(1);}else if let Some(cursor)=self.cursor.as_mut(){if !cursor.terminal_is_empty(){cursor.begin_close();p=cursor.close_step(RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes-META,maximum_depth:grant.maximum_depth-1,..grant})?.progress;p.copied_bytes+=META;p.copied_items=p.copied_items.max(1);}else{self.cursor=None;}}else{self.digest=None;self.bytes=0;self.phase=8;}Ok(p)}
 pub fn close_demand(&self)->RetirementDemand{if self.terminal_is_empty(){return Default::default();}if !self.birth.terminal_is_empty(){let mut d=self.birth.close_demand();d.copy_bytes+=META;d.depth+=1;return d;}match self.cursor.as_ref(){Some(cursor)if !cursor.terminal_is_empty()=>RetirementDemand{copy_bytes:size_of::<Cursor>()+META,depth:2,..Default::default()},Some(_)=>RetirementDemand{copy_bytes:META,release_bytes:size_of::<Cursor>(),depth:1,..Default::default()},None=>RetirementDemand{copy_bytes:size_of::<Self>(),depth:1,..Default::default()}}}
}